import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { useParams, useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { ArrowLeft, Download, FileText, Eye, Settings } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import type { Quiz } from "@shared/schema";
import { generateQuizPDF } from "@/utils/quiz-pdf-generator";

export default function QuizPDF() {
  const { id } = useParams();
  const [, setLocation] = useLocation();
  const { toast } = useToast();

  const [options, setOptions] = useState({
    includeAnswerKey: true,
    includeQRCode: true,
    orientation: 'portrait' as 'portrait' | 'landscape',
    downloadAutomatically: true
  });

  const [isGenerating, setIsGenerating] = useState(false);

  const { data: quiz, isLoading } = useQuery<Quiz>({
    queryKey: ["/api/quizzes", id],
    enabled: !!id
  });

  const handleGeneratePDF = async () => {
    if (!quiz) return;

    setIsGenerating(true);

    try {
      toast({
        title: "Generating PDF...",
        description: "Your professionally formatted quiz PDF is being created.",
      });

      await generateQuizPDF(quiz, {
        includeQRCode: options.includeQRCode,
        includeAnswerKey: options.includeAnswerKey,
        orientation: options.orientation
      });

      toast({
        title: "PDF Generated Successfully",
        description: "Your quiz PDF has been downloaded with all requested formatting.",
      });
    } catch (error) {
      console.error('PDF generation error:', error);
      toast({
        title: "PDF Generation Failed",
        description: "There was an error creating your PDF. Please try again.",
        variant: "destructive",
      });
    } finally {
      setIsGenerating(false);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-abraj-primary mx-auto mb-4"></div>
          <p className="text-lg text-gray-600">Loading quiz...</p>
        </div>
      </div>
    );
  }

  if (!quiz) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Card className="w-full max-w-md">
          <CardContent className="pt-6 text-center">
            <p className="text-lg text-gray-600 mb-4">Quiz not found</p>
            <Button onClick={() => setLocation("/")} className="abraj-primary">
              Go Home
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  const questions = quiz.questions as any[];

  return (
    <div className="min-h-screen py-8 bg-gray-50">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="mb-8">
          <Button
            variant="ghost"
            onClick={() => setLocation("/")}
            className="mb-4 text-gray-600 hover:text-gray-800"
          >
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back to Home
          </Button>

          <div className="text-center">
            <h1 className="font-bold text-4xl text-gray-800 mb-4 flex items-center justify-center gap-3">
              <FileText className="w-10 h-10 text-abraj-primary" />
              Generate Quiz PDF
            </h1>
            <p className="text-xl text-gray-600">Create a professionally formatted PDF document</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Quiz Preview */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Eye className="w-5 h-5 text-abraj-primary" />
                Quiz Preview
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                <div>
                  <h3 className="font-bold text-xl text-abraj-primary">{quiz.title}</h3>
                  {quiz.description && (
                    <p className="text-gray-600 mt-2">{quiz.description}</p>
                  )}
                </div>

                <div className="bg-gray-50 p-4 rounded-lg">
                  <h4 className="font-semibold text-gray-800 mb-2">Quiz Statistics</h4>
                  <div className="grid grid-cols-2 gap-4 text-sm">
                    <div>
                      <span className="text-gray-600">Total Questions:</span>
                      <span className="font-semibold ml-2">{questions.length}</span>
                    </div>
                    <div>
                      <span className="text-gray-600">Quiz ID:</span>
                      <span className="font-semibold ml-2">{quiz.id}</span>
                    </div>
                    <div>
                      <span className="text-gray-600">Created:</span>
                      <span className="font-semibold ml-2">
                        {new Date(quiz.createdAt || Date.now()).toLocaleDateString()}
                      </span>
                    </div>
                    <div>
                      <span className="text-gray-600">Background:</span>
                      <span className="font-semibold ml-2 capitalize">{quiz.background}</span>
                    </div>
                  </div>
                </div>

                <div className="max-h-60 overflow-y-auto">
                  <h4 className="font-semibold text-gray-800 mb-2">Questions Preview</h4>
                  {questions.slice(0, 3).map((question, index) => (
                    <div key={index} className="mb-3 p-3 bg-white rounded-lg border">
                      <p className="font-medium text-sm">
                        {index + 1}. {question.question.slice(0, 100)}
                        {question.question.length > 100 ? '...' : ''}
                      </p>
                      <p className="text-xs text-gray-500 mt-1">
                        {question.answers.length} answer options
                      </p>
                    </div>
                  ))}
                  {questions.length > 3 && (
                    <p className="text-sm text-gray-500 text-center">
                      + {questions.length - 3} more questions
                    </p>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>

          {/* PDF Options */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Settings className="w-5 h-5 text-abraj-primary" />
                PDF Generation Options
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-6">
              {/* Orientation */}
              <div>
                <Label className="text-base font-semibold">Page Orientation</Label>
                <p className="text-sm text-gray-600 mb-3">
                  Landscape is recommended for longer questions or answers
                </p>
                <RadioGroup
                  value={options.orientation}
                  onValueChange={(value) => setOptions(prev => ({ ...prev, orientation: value as 'portrait' | 'landscape' }))}
                >
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem value="portrait" id="portrait" />
                    <Label htmlFor="portrait" className="cursor-pointer">
                      Portrait (Standard)
                    </Label>
                  </div>
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem value="landscape" id="landscape" />
                    <Label htmlFor="landscape" className="cursor-pointer">
                      Landscape (Wide format)
                    </Label>
                  </div>
                </RadioGroup>
              </div>

              {/* Content Options */}
              <div>
                <Label className="text-base font-semibold">Content Options</Label>
                <div className="space-y-3 mt-3">
                  <div className="flex items-center space-x-2">
                    <Checkbox
                      id="answerKey"
                      checked={options.includeAnswerKey}
                      onCheckedChange={(checked) => 
                        setOptions(prev => ({ ...prev, includeAnswerKey: !!checked }))
                      }
                    />
                    <Label htmlFor="answerKey" className="cursor-pointer">
                      Include Answer Key (correct answers highlighted)
                    </Label>
                  </div>

                  <div className="flex items-center space-x-2">
                    <Checkbox
                      id="qrCode"
                      checked={options.includeQRCode}
                      onCheckedChange={(checked) => 
                        setOptions(prev => ({ ...prev, includeQRCode: !!checked }))
                      }
                    />
                    <Label htmlFor="qrCode" className="cursor-pointer">
                      Include QR Code (link to online quiz)
                    </Label>
                  </div>
                </div>
              </div>

              {/* PDF Features */}
              <div className="bg-blue-50 p-4 rounded-lg">
                <h4 className="font-semibold text-blue-800 mb-2">Included Features</h4>
                <ul className="text-sm text-blue-700 space-y-1">
                  <li>✓ Professional Abraj branding and logo</li>
                  <li>✓ Numbered questions with clear formatting</li>
                  <li>✓ A, B, C, D labeled answer options</li>
                  <li>✓ Summary table with all correct answers</li>
                  <li>✓ Creation date and footer branding</li>
                  <li>✓ Page numbers and section headings</li>
                  <li>✓ Clean spacing and readable fonts</li>
                </ul>
              </div>

              {/* Generate Button */}
              <Button
                onClick={handleGeneratePDF}
                disabled={isGenerating}
                className="w-full h-12 text-lg font-bold abraj-primary hover:abraj-secondary"
              >
                {isGenerating ? (
                  <div className="flex items-center gap-2">
                    <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                    Generating PDF...
                  </div>
                ) : (
                  <div className="flex items-center gap-2">
                    <Download className="w-5 h-5" />
                    Generate & Download PDF
                  </div>
                )}
              </Button>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

client/src/pages/home.tsx.content:
import { useState, useEffect, useRef } from "react";
import { Link, useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Trophy, Clock, Image, Users, BarChart, BookOpen, Play, QrCode, X, Crown, Medal, Award } from "lucide-react";
import { useAuth } from "@/hooks/useAuth";
import { useQuery } from "@tanstack/react-query";
import { useToast } from "@/hooks/use-toast";

interface Quiz {
  id: number;
  title: string;
  description: string;
  createdBy: number;
  questions: Array<{
    question: string;
    answers: string[];
    correctAnswer: number;
    timeLimit: number;
  }>;
  isPublic: boolean;
  createdAt: string;
}

interface LatestResultsData {
  hasResults: boolean;
  game?: {
    gamePin: string;
    quizTitle: string;
    completedAt: string;
    totalQuestions: number;
  };
  top3Players?: Array<{
    name: string;
    score: number;
    rank: number;
  }>;
}

export default function Home() {
  const [gamePin, setGamePin] = useState("");
  const [playerName, setPlayerName] = useState("");
  const [showScanner, setShowScanner] = useState(false);
  const [, setLocation] = useLocation();
  const { user, isAuthenticated } = useAuth();
  const { toast } = useToast();
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Fetch user's quizzes when authenticated
  const { data: userQuizzes } = useQuery<Quiz[]>({
    queryKey: ["/api/my-quizzes"],
    enabled: isAuthenticated,
  });

  // Fetch latest quiz results
  const { data: latestResults } = useQuery<LatestResultsData>({
    queryKey: ["/api/latest-results"],
    refetchInterval: 30000, // Refresh every 30 seconds
  });

  // Auto-fill player name if user is authenticated
  useEffect(() => {
    if (isAuthenticated && user && !playerName) {
      setPlayerName(user.username);
    }
  }, [isAuthenticated, user, playerName]);

  // Camera access and QR scanning
  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } // Use back camera if available
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play();
      }
    } catch (error) {
      toast({
        title: "Camera Access Failed",
        description: "Please allow camera access to scan QR codes.",
        variant: "destructive",
      });
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
  };

  // Simple QR code detection function
  // In production, you would use a proper QR library like jsQR
  const scanQRCode = () => {
    if (!videoRef.current || !canvasRef.current) return;

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');

    if (!context || video.videoWidth === 0 || video.videoHeight === 0) return;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    context.drawImage(video, 0, 0, canvas.width, canvas.height);

    // For demonstration, we'll check if user clicks the video area to simulate scanning
    // In a real app, you'd integrate with jsQR or similar library
  };

  const handleVideoClick = () => {
    // Simulate QR code detection when user taps the video area
    const currentUrl = window.location.origin;
    const gamePin = prompt("For demo: Enter the game PIN from the QR code you're scanning:");

    if (gamePin && gamePin.trim()) {
      setGamePin(gamePin.trim());
      setShowScanner(false);
      stopCamera();
      toast({
        title: "QR Code Scanned!",
        description: `Game PIN ${gamePin.trim()} has been entered.`,
      });
    }
  };

  // Start scanning when camera is ready
  useEffect(() => {
    if (showScanner && videoRef.current) {
      startCamera();
      const interval = setInterval(scanQRCode, 500); // Scan every 500ms
      return () => {
        clearInterval(interval);
        stopCamera();
      };
    }
  }, [showScanner]);

  const handleScanClick = () => {
    setShowScanner(true);
  };

  const handleCloseScanner = () => {
    setShowScanner(false);
    stopCamera();
  };

  const handleJoinGame = () => {
    if (gamePin.trim()) {
      if (playerName.trim()) {
        setLocation(`/play/${gamePin.trim()}?player=${encodeURIComponent(playerName.trim())}`);
      } else {
        setLocation(`/join/${gamePin.trim()}`);
      }
    }
  };

  return (
    <div className="min-h-screen relative">
      {/* Background Gradient Overlay */}
      <div className="fixed inset-0 -z-10 bg-gradient-to-br from-blue-50 via-purple-50 to-pink-50 animate-gradient"></div>

      {/* Hero Section */}
      <section className="relative overflow-hidden py-16">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="max-w-4xl mx-auto text-center">

            {/* Main Content */}
            <div className="animate-scale-in">
              <h1 className="font-bold lg:text-6xl text-[59px] gradient-text">Powered by Our Dedicated Team</h1>
              <p className="mt-6 text-gray-600 max-w-2xl mx-auto text-[13px]">Abraj's innovative employees work tirelessly to create engaging educational experiences for learners worldwide.</p>

              {/* Game PIN Entry */}
              <Card className="mt-8 card-3d-enhanced glass max-w-lg mx-auto">
                <CardContent className="p-8">
                  <h3 className="font-bold text-2xl text-gray-800 mb-4">Join a game</h3>
                  <div className="space-y-4">
                    <div className="flex flex-col sm:flex-row gap-3">
                      <Input
                        type="text"
                        placeholder="Game PIN"
                        value={gamePin}
                        onChange={(e) => setGamePin(e.target.value)}
                        className="flex-1 px-4 py-3 rounded-xl text-lg font-medium text-center input-3d shimmer"
                        onKeyPress={(e) => e.key === 'Enter' && handleJoinGame()}
                      />
                      <Dialog open={showScanner} onOpenChange={setShowScanner}>
                        <DialogTrigger asChild>
                          <Button
                            variant="outline"
                            onClick={handleScanClick}
                            className="px-4 py-3 rounded-xl text-lg font-medium"
                            title="Scan QR Code"
                          >
