                    onChange={(e) => setQuiz(prev => ({ ...prev, description: e.target.value }))}
                    placeholder="Describe your quiz"
                    rows={3}
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Game Background</label>

                  {backgroundImage ? (
                    <div className="relative">
                      <div className="w-full h-32 bg-gray-100 rounded-lg border-2 border-dashed border-gray-300 relative overflow-hidden">
                        <img 
                          src={backgroundImage} 
                          alt="Background preview" 
                          className="w-full h-full object-cover rounded-lg"
                        />
                        <Button
                          type="button"
                          variant="destructive"
                          size="sm"
                          onClick={removeBackgroundImage}
                          className="absolute top-2 right-2 h-8 w-8 p-0"
                          data-testid="button-remove-background"
                        >
                          <X className="w-4 h-4" />
                        </Button>
                      </div>
                      <p className="text-xs text-gray-500 mt-1">Custom background image</p>
                    </div>
                  ) : (
                    <>
                      <div 
                        onClick={() => fileInputRef.current?.click()}
                        className="w-full h-32 bg-gray-100 rounded-lg border-2 border-dashed border-gray-300 flex flex-col items-center justify-center cursor-pointer hover:bg-gray-50 transition-colors mb-3"
                        data-testid="button-upload-background"
                      >
                        <Upload className="w-8 h-8 text-gray-400 mb-2" />
                        <p className="text-sm text-gray-600 font-medium">Upload Background Image</p>
                        <p className="text-xs text-gray-500">Click to select an image file</p>
                      </div>

                      <Button
                        type="button"
                        onClick={handleGenerateBackground}
                        disabled={generateBackgroundMutation.isPending || !quiz.title || quiz.title.trim().length < 3}
                        className="w-full abraj-primary hover:abraj-secondary text-white"
                        data-testid="button-generate-background"
                      >
                        {generateBackgroundMutation.isPending ? (
                          <>
                            <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                            Generating...
                          </>
                        ) : (
                          <>
                            <Wand2 className="w-4 h-4 mr-2" />
                            Generate Background with AI
                          </>
                        )}
                      </Button>
                    </>
                  )}

                  <input
                    ref={fileInputRef}
                    type="file"
                    accept="image/*"
                    onChange={handleImageUpload}
                    className="hidden"
                  />

                  <p className="text-xs text-gray-500 mt-2">
                    {backgroundImage 
                      ? "Background will be used throughout the game session" 
                      : "Upload an image or generate one with AI based on your quiz title"}
                  </p>
                </div>

                <div className="text-center">
                  <span className="text-sm text-gray-600">
                    {(quiz.questions && quiz.questions.length) || 0} question{((quiz.questions && quiz.questions.length) || 0) !== 1 ? 's' : ''}
                  </span>
                </div>
              </CardContent>
            </Card>

            {/* Question Navigation */}
            <Card>
              <CardHeader>
                <CardTitle>Questions</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  {(quiz.questions && quiz.questions.length > 0) ? quiz.questions.map((q, index) => (
                    <div
                      key={index}
                      className={`flex items-center justify-between p-2 rounded-lg cursor-pointer transition-colors ${
                        index === currentQuestionIndex 
                          ? 'bg-teal-100 border-2 border-abraj-primary' 
                          : 'bg-gray-50 hover:bg-gray-100'
                      }`}
                      onClick={() => setCurrentQuestionIndex(index)}
                    >
                      <span className="text-sm font-medium">
                        Q{index + 1}: {q.question || "Untitled"}
                      </span>
                      {quiz.questions.length > 1 && (
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={(e) => {
                            e.stopPropagation();
                            removeQuestion(index);
                          }}
                          className="text-red-500 hover:text-red-700"
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      )}
                    </div>
                  )) : (
                    <div className="text-center text-gray-500 p-4">
                      No questions yet. Add a question to get started.
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Question Editor */}
          <div className="lg:col-span-2">
            <Card>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle>Question {currentQuestionIndex + 1} of {quiz.questions.length}</CardTitle>
                  <Badge variant="secondary">Multiple Choice</Badge>
                </div>
              </CardHeader>
              <CardContent className="space-y-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Question</label>
                  <Input
                    value={currentQuestion.question}
                    onChange={(e) => updateQuestion(currentQuestionIndex, 'question', e.target.value)}
                    placeholder="Enter your question"
                    className="text-lg"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-4">Answer Options</label>
                  <div className="space-y-4">
                    {currentQuestion.answers.map((answer, answerIndex) => {
                      const IconComponent = answerIcons[answerIndex];
                      const colorClass = answerColors[answerIndex];

                      return (
                        <div
                          key={answerIndex}
                          className={`${colorClass} text-white p-4 rounded-lg cursor-pointer hover:scale-105 transition-transform`}
                        >
                          <div className="flex items-center justify-end mb-2">
                            <IconComponent className="w-5 h-5" />
                          </div>
                          <Input
                            value={answer}
                            onChange={(e) => updateAnswer(currentQuestionIndex, answerIndex, e.target.value)}
                            placeholder={`Answer option ${answerIndex + 1}`}
                            className="w-full border-none text-white placeholder:text-white/70 focus:outline-none bg-[#ffffff85]"
                          />
                          <div className="flex items-center space-x-2 mt-2">
                            <Checkbox
                              checked={currentQuestion.correctAnswer === answerIndex}
                              onCheckedChange={(checked) => {
                                if (checked) {
                                  updateQuestion(currentQuestionIndex, 'correctAnswer', answerIndex);
                                }
                              }}
                              className="border-white data-[state=checked]:bg-white data-[state=checked]:text-black"
                            />
                            <span className="text-sm opacity-90">Correct answer</span>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>

                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-4">
                    <label className="text-sm font-medium text-gray-700">Time limit:</label>
                    <select
                      value={currentQuestion.timeLimit}
                      onChange={(e) => updateQuestion(currentQuestionIndex, 'timeLimit', parseInt(e.target.value))}
                      className="border border-gray-300 rounded-md px-3 py-1"
                    >
                      <option value={5}>5 seconds</option>
                      <option value={10}>10 seconds</option>
                      <option value={15}>15 seconds</option>
                      <option value={20}>20 seconds</option>
                      <option value={30}>30 seconds</option>
                      <option value={60}>60 seconds</option>
                    </select>
                  </div>

                  <div className="flex space-x-3">
                    <Button
                      variant="outline"
                      onClick={() => setCurrentQuestionIndex(Math.max(0, currentQuestionIndex - 1))}
                      disabled={currentQuestionIndex === 0}
                    >
                      Previous
                    </Button>
                    <Button
                      variant="outline"
                      onClick={() => setCurrentQuestionIndex(Math.min(quiz.questions.length - 1, currentQuestionIndex + 1))}
                      disabled={currentQuestionIndex === quiz.questions.length - 1}
                    >
                      Next
                    </Button>
                  </div>
                </div>

                <div className="flex justify-center mt-4">
                  <Button onClick={addQuestion} size="sm" className="abraj-primary">
                    <Plus className="w-4 h-4 mr-1" />
                    Add Question
                  </Button>
                </div>
              </CardContent>
            </Card>

            {/* Submit */}
            <div className="mt-8 flex justify-center gap-4">
              <Button
                onClick={handleDownloadPDF}
                variant="outline"
                className="h-10 px-6 py-3 text-lg font-bold border-[#019ebd] text-[#019ebd] hover:bg-[#019ebd] hover:text-white transition-colors"
              >
                <Download className="w-5 h-5 mr-2" />
                Download PDF
              </Button>
              <Button
                onClick={handleSubmit}
                disabled={createQuizMutation.isPending}
                className="hover:bg-primary/90 h-10 abraj-primary hover:abraj-secondary px-8 py-3 text-lg font-bold bg-[#22c55e] text-[#ffffff]"
              >
                {createQuizMutation.isPending ? "Creating..." : "Create Quiz"}
              </Button>
                </div>
              </div>
            </div>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

client/src/components/ui/badge.tsx.content:
import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const badgeVariants = cva(
  "inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
  {
    variants: {
      variant: {
        default:
          "border-transparent bg-primary text-primary-foreground hover:bg-primary/80",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
        destructive:
          "border-transparent bg-destructive text-destructive-foreground hover:bg-destructive/80",
        outline: "text-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return (
    <div className={cn(badgeVariants({ variant }), className)} {...props} />
  )
}

export { Badge, badgeVariants }

client/src/pages/create-quiz-simple.tsx.content:
import { useState, useRef } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Plus, X, Image, ChevronLeft, ChevronRight } from "lucide-react";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";
import type { Question } from "@shared/schema";

export default function CreateQuizSimple() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const { user } = useAuth();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [quiz, setQuiz] = useState({
    title: "",
    description: "",
    questions: [
      {
        question: "",
        answers: ["", "", "", ""],
        correctAnswer: 0,
        timeLimit: 10
      }
    ] as Question[],
    background: "classroom",
    isPublic: true
  });

  const [backgroundImage, setBackgroundImage] = useState<string | null>(null);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);

  // Handle background image upload
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      // Check file type
      if (!file.type.startsWith('image/')) {
        toast({
          title: "Invalid file type",
          description: "Please select an image file (JPG, PNG, GIF, etc.)",
          variant: "destructive",
        });
        return;
      }

      // Check file size (limit to 5MB)
      if (file.size > 5 * 1024 * 1024) {
        toast({
          title: "File too large",
          description: "Please select an image smaller than 5MB",
          variant: "destructive",
        });
        return;
      }

      const reader = new FileReader();
      reader.onload = (e) => {
        const dataUrl = e.target?.result as string;
        setBackgroundImage(dataUrl);
        setQuiz(prev => ({ ...prev, background: dataUrl }));
      };
      reader.readAsDataURL(file);
    }
  };

  const removeBackgroundImage = () => {
    setBackgroundImage(null);
    setQuiz(prev => ({ ...prev, background: 'classroom' }));
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const createQuizMutation = useMutation({
    mutationFn: async (data: typeof quiz) => {
      if (!user?.id) {
        throw new Error("You must be logged in to create a quiz");
      }

      const payload = {
        ...data,
        createdBy: user.id
      };

      console.log("Sending quiz data:", payload);
      const response = await apiRequest("POST", "/api/quizzes", payload);
      return response.json();
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["/api/quizzes"] });
      toast({
        title: "Success!",
        description: "Quiz created successfully. You can now host a game.",
      });
      setLocation(`/host-quiz/${data.id}`);
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to create quiz",
        variant: "destructive",
      });
    }
  });

  const addQuestion = () => {
    const newQuestion: Question = {
      question: "",
      answers: ["", "", "", ""],
      correctAnswer: 0,
      timeLimit: 10
    };
    setQuiz(prev => ({
      ...prev,
      questions: [...prev.questions, newQuestion]
    }));
    setCurrentQuestionIndex(quiz.questions.length);
  };

  const removeQuestion = (index: number) => {
    if (quiz.questions.length <= 1) {
      toast({
        title: "Cannot remove question",
        description: "Quiz must have at least one question.",
        variant: "destructive",
      });
      return;
    }

    setQuiz(prev => ({
      ...prev,
      questions: prev.questions.filter((_, i) => i !== index)
    }));

    if (currentQuestionIndex >= index && currentQuestionIndex > 0) {
      setCurrentQuestionIndex(currentQuestionIndex - 1);
    }
  };

  const updateQuestion = (index: number, field: keyof Question, value: any) => {
    setQuiz(prev => ({
      ...prev,
      questions: prev.questions.map((q, i) => 
        i === index ? { ...q, [field]: value } : q
      )
    }));
  };

  const updateAnswer = (questionIndex: number, answerIndex: number, value: string) => {
    setQuiz(prev => ({
      ...prev,
      questions: prev.questions.map((q, i) => 
        i === questionIndex ? {
          ...q,
          answers: q.answers.map((a, ai) => ai === answerIndex ? value : a)
        } : q
      )
    }));
  };

  const handleSubmit = () => {
    // Validate quiz title
    if (!quiz.title.trim()) {
      toast({
        title: "Error",
        description: "Please enter a quiz title.",
        variant: "destructive",
      });
      return;
    }

    // Validate questions
    for (let i = 0; i < quiz.questions.length; i++) {
      const question = quiz.questions[i];

      if (!question.question.trim()) {
        toast({
          title: "Error",
          description: `Question ${i + 1} text is required.`,
          variant: "destructive",
        });
        return;
      }

      // Check if all answers are filled
      for (let j = 0; j < question.answers.length; j++) {
        if (!question.answers[j].trim()) {
          toast({
            title: "Error",
            description: `Question ${i + 1}, Answer option ${j + 1} is required.`,
            variant: "destructive",
          });
          return;
        }
      }

      // Validate time limit
      if (question.timeLimit < 5 || question.timeLimit > 120) {
        toast({
          title: "Error",
          description: `Question ${i + 1} time limit must be between 5 and 120 seconds.`,
          variant: "destructive",
        });
        return;
      }
    }

    // All validations passed, create the quiz
    createQuizMutation.mutate(quiz);
  };

  const currentQuestion = quiz.questions[currentQuestionIndex] || {
    question: "",
    answers: ["", "", "", ""],
    correctAnswer: 0,
    timeLimit: 10
  };

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold text-gray-900 mb-2">Create Your Quiz</h1>
          <p className="text-gray-600">Build engaging quizzes with custom backgrounds</p>
        </div>

        <div className="grid lg:grid-cols-3 gap-8">
          {/* Quiz Details */}
          <div className="lg:col-span-1 space-y-6">
            <Card>
              <CardHeader>
                <CardTitle>Quiz Details</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Title</label>
                  <Input
                    value={quiz.title}
                    onChange={(e) => setQuiz(prev => ({ ...prev, title: e.target.value }))}
                    placeholder="Enter quiz title"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Description</label>
                  <Textarea
                    value={quiz.description}
                    onChange={(e) => setQuiz(prev => ({ ...prev, description: e.target.value }))}
                    placeholder="Enter quiz description"
                    rows={3}
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Game Background</label>

                  {backgroundImage ? (
                    <div className="relative">
                      <div className="w-full h-32 bg-gray-100 rounded-lg border-2 border-dashed border-gray-300 relative overflow-hidden">
                        <img 
                          src={backgroundImage} 
                          alt="Background preview" 
                          className="w-full h-full object-cover rounded-lg"
                        />
                        <Button
                          type="button"
                          variant="destructive"
                          size="sm"
                          onClick={removeBackgroundImage}
                          className="absolute top-2 right-2 h-8 w-8 p-0"
                        >
                          <X className="w-4 h-4" />
                        </Button>
                      </div>
                      <p className="text-xs text-gray-500 mt-1">Custom background image uploaded</p>
                    </div>
                  ) : (
                    <div 
                      onClick={() => fileInputRef.current?.click()}
                      className="w-full h-32 bg-gray-100 rounded-lg border-2 border-dashed border-gray-300 flex flex-col items-center justify-center cursor-pointer hover:bg-gray-50 transition-colors"
                    >
                      <Image className="w-8 h-8 text-gray-400 mb-2" />
                      <p className="text-sm text-gray-600 font-medium">Upload Background Image</p>
                      <p className="text-xs text-gray-500">Click to select an image file</p>
                    </div>
                  )}

                  <input
                    ref={fileInputRef}
                    type="file"
                    accept="image/*"
                    onChange={handleImageUpload}
                    className="hidden"
                  />

                  <p className="text-xs text-gray-500 mt-1">
                    This background will be used throughout the game session. Maximum file size: 5MB
                  </p>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle>Questions Summary</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  {quiz.questions.map((_, index) => (
                    <div
                      key={index}
                      onClick={() => setCurrentQuestionIndex(index)}
                      className={`p-3 rounded-lg cursor-pointer transition-colors ${
                        index === currentQuestionIndex
                          ? "bg-[#019ebd] text-white"
                          : "bg-gray-100 hover:bg-gray-200"
                      }`}
                    >
                      <div className="flex items-center justify-between">
                        <span className="font-medium">Question {index + 1}</span>
                        {quiz.questions.length > 1 && (
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={(e) => {
                              e.stopPropagation();
                              removeQuestion(index);
                            }}
                            className={`h-6 w-6 p-0 ${
                              index === currentQuestionIndex
                                ? "text-white hover:bg-white/20"
                                : "text-gray-500 hover:text-red-600"
                            }`}
                          >
                            <X className="w-4 h-4" />
                          </Button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>

                <Button
                  onClick={addQuestion}
                  variant="outline"
                  className="w-full mt-4"
                >
                  <Plus className="w-4 h-4 mr-2" />
                  Add Question
                </Button>
              </CardContent>
            </Card>
          </div>

          {/* Question Editor */}
          <div className="lg:col-span-2">
            <Card>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle>Question {currentQuestionIndex + 1} of {quiz.questions.length}</CardTitle>
                  <div className="flex items-center space-x-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setCurrentQuestionIndex(Math.max(0, currentQuestionIndex - 1))}
                      disabled={currentQuestionIndex === 0}
                    >
                      <ChevronLeft className="w-4 h-4" />
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setCurrentQuestionIndex(Math.min(quiz.questions.length - 1, currentQuestionIndex + 1))}
                      disabled={currentQuestionIndex === quiz.questions.length - 1}
                    >
                      <ChevronRight className="w-4 h-4" />
                    </Button>
                  </div>
                </div>
              </CardHeader>
              <CardContent className="space-y-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Question Text</label>
                  <Textarea
                    value={currentQuestion.question}
                    onChange={(e) => updateQuestion(currentQuestionIndex, "question", e.target.value)}
                    placeholder="Enter your question here..."
                    rows={3}
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-3">Answer Options</label>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {currentQuestion.answers.map((answer, answerIndex) => (
                      <div key={answerIndex} className="space-y-2">
                        <div className="flex items-center space-x-2">
                          <Input
                            value={answer}
                            onChange={(e) => updateAnswer(currentQuestionIndex, answerIndex, e.target.value)}
                            placeholder={`Answer option ${answerIndex + 1}`}
                            className="flex-1"
                          />
                        </div>
                        <div className="ml-10">
                          <label className="flex items-center space-x-2">
                            <input
                              type="radio"
                              name={`correct-answer-${currentQuestionIndex}`}
                              checked={currentQuestion.correctAnswer === answerIndex}
                              onChange={() => updateQuestion(currentQuestionIndex, "correctAnswer", answerIndex)}
                              className="text-green-500"
                            />
                            <span className="text-sm text-gray-600">Correct answer</span>
                          </label>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Time Limit (seconds)</label>
                  <div className="flex items-center space-x-4">
                    <Input
                      type="number"
                      min="5"
                      max="120"
                      value={currentQuestion.timeLimit}
                      onChange={(e) => updateQuestion(currentQuestionIndex, "timeLimit", parseInt(e.target.value) || 10)}
                      className="w-24"
                    />
                    <div className="flex space-x-2">
                      {[5, 10, 15, 20, 30, 60].map((time) => (
                        <Button
                          key={time}
                          type="button"
                          variant={currentQuestion.timeLimit === time ? "default" : "outline"}
                          size="sm"
                          onClick={() => updateQuestion(currentQuestionIndex, "timeLimit", time)}
                        >
                          {time}s
                        </Button>
                      ))}
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>

            <div className="mt-6 flex justify-end space-x-4">
              <Button
                variant="outline"
                onClick={() => setLocation("/")}
              >
                Cancel
              </Button>
              <Button
                onClick={handleSubmit}
                disabled={createQuizMutation.isPending}
                className="abraj-primary hover:abraj-secondary text-white"
              >
                {createQuizMutation.isPending ? "Creating..." : "Create Quiz"}
              </Button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

client/src/components/ui/breadcrumb.tsx.content:
import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { ChevronRight, MoreHorizontal } from "lucide-react"

import { cn } from "@/lib/utils"

const Breadcrumb = React.forwardRef<
  HTMLElement,
  React.ComponentPropsWithoutRef<"nav"> & {
    separator?: React.ReactNode
  }
>(({ ...props }, ref) => <nav ref={ref} aria-label="breadcrumb" {...props} />)
Breadcrumb.displayName = "Breadcrumb"

const BreadcrumbList = React.forwardRef<
  HTMLOListElement,
  React.ComponentPropsWithoutRef<"ol">
>(({ className, ...props }, ref) => (
  <ol
    ref={ref}
    className={cn(
      "flex flex-wrap items-center gap-1.5 break-words text-sm text-muted-foreground sm:gap-2.5",
      className
    )}
    {...props}
  />
))
BreadcrumbList.displayName = "BreadcrumbList"

const BreadcrumbItem = React.forwardRef<
  HTMLLIElement,
  React.ComponentPropsWithoutRef<"li">
>(({ className, ...props }, ref) => (
  <li
    ref={ref}
    className={cn("inline-flex items-center gap-1.5", className)}
    {...props}
  />
))
BreadcrumbItem.displayName = "BreadcrumbItem"

const BreadcrumbLink = React.forwardRef<
  HTMLAnchorElement,
  React.ComponentPropsWithoutRef<"a"> & {
    asChild?: boolean
  }
>(({ asChild, className, ...props }, ref) => {
  const Comp = asChild ? Slot : "a"

  return (
    <Comp
      ref={ref}
      className={cn("transition-colors hover:text-foreground", className)}
      {...props}
    />
  )
})
BreadcrumbLink.displayName = "BreadcrumbLink"

const BreadcrumbPage = React.forwardRef<
  HTMLSpanElement,
  React.ComponentPropsWithoutRef<"span">
>(({ className, ...props }, ref) => (
  <span
    ref={ref}
    role="link"
    aria-disabled="true"
    aria-current="page"
    className={cn("font-normal text-foreground", className)}
    {...props}
  />
))
BreadcrumbPage.displayName = "BreadcrumbPage"

const BreadcrumbSeparator = ({
  children,
  className,
  ...props
}: React.ComponentProps<"li">) => (
  <li
    role="presentation"
    aria-hidden="true"
    className={cn("[&>svg]:w-3.5 [&>svg]:h-3.5", className)}
    {...props}
  >
    {children ?? <ChevronRight />}
  </li>
)
BreadcrumbSeparator.displayName = "BreadcrumbSeparator"

const BreadcrumbEllipsis = ({
  className,
  ...props
}: React.ComponentProps<"span">) => (
  <span
    role="presentation"
    aria-hidden="true"
    className={cn("flex h-9 w-9 items-center justify-center", className)}
    {...props}
  >
    <MoreHorizontal className="h-4 w-4" />
    <span className="sr-only">More</span>
  </span>
)
BreadcrumbEllipsis.displayName = "BreadcrumbElipssis"

export {
  Breadcrumb,
  BreadcrumbList,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbPage,
  BreadcrumbSeparator,
  BreadcrumbEllipsis,
}

